parameters.text:
=Here is an email from a customer requesting a shipment:

Subject: {{ $json.subject }}
Body: {{ $json.text }}

Please extract all the structured logistics data based on the format provided.

=Here is the output:

- Shipment Number: {{ $json.shipment_number }}
- Pickup Location: {{ $json.pickup_location }}
- Pickup Address: {{ $json.pickup_address }}  
- Expected Pickup Time: {{ $json.expected_pickup_time }}  
- Temperature Control: {{ $json.temperature_control }}  
- Destination: {{ $json.destination_store_name }} 
- Destination Address: {{ $json.destination_address }}
- Expected Delivery Time: {{ $json.expected_delivery_time }} 
- Driving Distance: {{ $json.driving_distance }} km
- Estimated Transit Time: {{ $json.driving_time }} min
- Contact Name: {{ $('AI Agent Parser').item.json.output.sender_name }}
- Contact Company: {{ $('AI Agent Parser').item.json.output.sender_company }}

parameters.jsCode:
const itemsIn = $input.all();

if (itemsIn.length < 2) {
  throw new Error('Se esperaban al menos 2 items: origen y destino');
}

const pickup = itemsIn[0].json;
const destination = itemsIn[1].json;

return [
  {
    json: {
      pickup_longitude: pickup.p_longitude ?? null,
      pickup_latitude: pickup.p_latitude ?? null,
      destination_longitude: destination.d_longitude ?? null,
      destination_latitude: destination.d_latitude ?? null,
      borough: pickup.borough ?? destination.borough ?? null,
      neighborhood: pickup.neighborhood ?? destination.neighborhood ?? null,
      locationmin: pickup.locationmin ?? destination.locationmin ?? null,
    }
  }
];
